arguments.file_text:
@page "/settings"
@using sv_5230899e7e7d40e888b8504ac2ada598.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <nav class="settings-sidebar">
        <h2>Settings</h2>
        <ul>
            @foreach (var section in _sections)
            {
                <li class="@(ActiveSection == section.Key ? "active" : "")" @onclick="() => ActiveSection = section.Key">
                    <span class="nav-icon">@section.Value.Icon</span>
                    <span>@section.Value.Label</span>
                </li>
            }
        </ul>
    </nav>

    <main class="settings-content">
        @if (_loading)
        {
            <div class="loading">Loading settings...</div>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "profile":
                    @RenderProfileSection()
                    break;
                case "notifications":
                    @RenderNotificationsSection()
                    break;
                case "security":
                    @RenderSecuritySection()
                    break;
                case "appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }

        @if (!string.IsNullOrEmpty(_toastMessage))
        {
            <div class="toast @_toastType">@_toastMessage</div>
        }
    </main>
</div>

@* Confirmation dialog *@
@if (_showConfirmDialog)
{
    <div class="dialog-overlay" @onclick="CancelConfirmDialog">
        <div class="dialog" @onclick:stopPropagation="true">
            <h3>Confirm Action</h3>
            <p>@_confirmMessage</p>
            <div class="dialog-actions">
                <button class="btn btn-secondary" @onclick="CancelConfirmDialog">Cancel</button>
                <button class="btn btn-danger" @onclick="ConfirmAction">Confirm</button>
            </div>
        </div>
    </div>
}

@code {
    private string ActiveSection { get; set; } = "profile";
    private bool _loading = true;
    private string? _toastMessage;
    private string _toastType = "success";
    private CancellationTokenSource? _toastCts;

    // Profile state
    private UserProfile? _savedProfile;
    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";

    // Notifications state
    private NotificationPrefs? _notificationPrefs;
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<string> _allChannels = ["general", "random", "announcements", "engineering", "design"];
    private HashSet<string> _mutedChannels = [];

    // Security state
    private SecuritySettings? _securitySettings;
    private bool _changePasswordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _twoFactorEnabled;

    // Appearance state
    private AppearanceSettings? _appearanceSettings;
    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    // Confirm dialog state
    private bool _showConfirmDialog;
    private string _confirmMessage = "";
    private Func<Task>? _confirmCallback;

    private readonly Dictionary<string, (string Label, string Icon)> _sections = new()
    {
        ["profile"] = ("Profile", "👤"),
        ["notifications"] = ("Notifications", "🔔"),
        ["security"] = ("Security", "🔒"),
        ["appearance"] = ("Appearance", "🎨")
    };

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
        _loading = false;
    }

    private async Task LoadAllSettings()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        _savedProfile = profileTask.Result;
        LoadProfileFields(_savedProfile);

        _notificationPrefs = notifTask.Result;
        _emailNotifications = _notificationPrefs.EmailNotifications;
        _pushNotifications = _notificationPrefs.PushNotifications;
        _weeklyDigest = _notificationPrefs.WeeklyDigest;
        _mutedChannels = [.. _notificationPrefs.MutedChannels];

        _securitySettings = securityTask.Result;
        _twoFactorEnabled = _securitySettings.TwoFactorEnabled;

        _appearanceSettings = appearanceTask.Result;
        _theme = _appearanceSettings.Theme;
        _fontSize = _appearanceSettings.FontSize;
        _language = _appearanceSettings.Language;
        _compactMode = _appearanceSettings.CompactMode;
    }

    private void LoadProfileFields(UserProfile profile)
    {
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _avatarUrl = profile.AvatarUrl;
        _bio = profile.Bio;
    }

    private async Task ShowToast(string message, string type = "success")
    {
        _toastCts?.Cancel();
        _toastCts = new CancellationTokenSource();
        _toastMessage = message;
        _toastType = type;
        StateHasChanged();

        try
        {
            await Task.Delay(3000, _toastCts.Token);
            _toastMessage = null;
            StateHasChanged();
        }
        catch (TaskCanceledException) { }
    }

    // Profile methods
    private async Task SaveProfile()
    {
        var profile = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        await ShowToast("Profile saved successfully!");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
            LoadProfileFields(_savedProfile);
    }

    // Notifications methods
    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, [.. _mutedChannels]);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _notificationPrefs = prefs;
        await ShowToast("Notification preferences saved!");
    }

    private void ToggleChannelMute(string channel)
    {
        if (!_mutedChannels.Remove(channel))
            _mutedChannels.Add(channel);
    }

    // Security methods
    private async Task ChangePassword()
    {
        if (_newPassword != _confirmPassword)
        {
            await ShowToast("Passwords do not match.", "error");
            return;
        }
        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            await ShowToast("Please fill in all password fields.", "error");
            return;
        }

        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _changePasswordExpanded = false;
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        await ShowToast("Password updated successfully!");
    }

    private void RequestRevokeSession(string sessionId, string device)
    {
        _confirmMessage = $"Are you sure you want to revoke the session on \"{device}\"? The user will be signed out.";
        _confirmCallback = async () => await RevokeSession(sessionId);
        _showConfirmDialog = true;
    }

    private async Task RevokeSession(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        await ShowToast("Session revoked.");
    }

    private void CancelConfirmDialog()
    {
        _showConfirmDialog = false;
        _confirmCallback = null;
    }

    private async Task ConfirmAction()
    {
        _showConfirmDialog = false;
        if (_confirmCallback is not null)
        {
            await _confirmCallback();
            _confirmCallback = null;
        }
    }

    // Appearance methods
    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _appearanceSettings = settings;
        await ShowToast("Appearance settings saved!");
    }

    // Render fragments
    private RenderFragment RenderProfileSection() => __builder =>
    {
        <section class="settings-section">
            <h2>Profile</h2>

            <div class="avatar-area">
                <div class="avatar-preview">
                    <img src="@_avatarUrl" alt="Avatar" />
                </div>
                <div class="avatar-url">
                    <label>Avatar URL</label>
                    <input type="text" @bind="_avatarUrl" />
                </div>
            </div>

            <div class="form-group">
                <label>Display Name</label>
                <input type="text" @bind="_displayName" />
            </div>

            <div class="form-group">
                <label>Email</label>
                <input type="email" @bind="_email" />
            </div>

            <div class="form-group">
                <label>Bio</label>
                <textarea rows="4" @bind="_bio"></textarea>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </section>
    };

    private RenderFragment RenderNotificationsSection() => __builder =>
    {
        <section class="settings-section">
            <h2>Notifications</h2>

            <div class="toggle-group">
                <label class="toggle-row">
                    <span>Email Notifications</span>
                    <input type="checkbox" @bind="_emailNotifications" class="toggle-switch" />
                </label>
                <label class="toggle-row">
                    <span>Push Notifications</span>
                    <input type="checkbox" @bind="_pushNotifications" class="toggle-switch" />
                </label>
                <label class="toggle-row">
                    <span>Weekly Digest</span>
                    <input type="checkbox" @bind="_weeklyDigest" class="toggle-switch" />
                </label>
            </div>

            <h3>Muted Channels</h3>
            <div class="channel-list">
                @foreach (var channel in _allChannels)
                {
                    <label class="channel-item">
                        <input type="checkbox" checked="@_mutedChannels.Contains(channel)" @onchange="() => ToggleChannelMute(channel)" />
                        <span>#@channel</span>
                        @if (_mutedChannels.Contains(channel))
                        {
                            <span class="muted-badge">muted</span>
                        }
                    </label>
                }
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
            </div>
        </section>
    };

    private RenderFragment RenderSecuritySection() => __builder =>
    {
        <section class="settings-section">
            <h2>Security</h2>

            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => _changePasswordExpanded = !_changePasswordExpanded">
                    <span>Change Password</span>
                    <span class="expand-icon">@(_changePasswordExpanded ? "▾" : "▸")</span>
                </button>
                @if (_changePasswordExpanded)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label>Current Password</label>
                            <input type="password" @bind="_currentPassword" />
                        </div>
                        <div class="form-group">
                            <label>New Password</label>
                            <input type="password" @bind="_newPassword" />
                        </div>
                        <div class="form-group">
                            <label>Confirm Password</label>
                            <input type="password" @bind="_confirmPassword" />
                        </div>
                        <button class="btn btn-primary" @onclick="ChangePassword">Update Password</button>
                    </div>
                }
            </div>

            <div class="two-factor-row">
                <div>
                    <strong>Two-Factor Authentication</strong>
                    <span class="status-indicator @(_twoFactorEnabled ? "enabled" : "disabled")">
                        @(_twoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </div>
                <label class="toggle-row">
                    <input type="checkbox" @bind="_twoFactorEnabled" class="toggle-switch" />
                </label>
            </div>

            @if (_securitySettings?.LastPasswordChange is not null)
            {
                <p class="info-text">Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }

            <h3>Active Sessions</h3>
            <div class="sessions-table-wrapper">
                <table class="sessions-table">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @if (_securitySettings?.Sessions is not null)
                        {
                            @foreach (var session in _securitySettings.Sessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@FormatLastActive(session.LastActive)</td>
                                    <td>
                                        @if (session.Id != _securitySettings.Sessions.FirstOrDefault()?.Id)
                                        {
                                            <button class="btn btn-danger btn-sm" @onclick="() => RequestRevokeSession(session.Id, session.Device)">Revoke</button>
                                        }
                                        else
                                        {
                                            <span class="current-badge">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        }
                    </tbody>
                </table>
            </div>
        </section>
    };

    private RenderFragment RenderAppearanceSection() => __builder =>
    {
        <section class="settings-section">
            <h2>Appearance</h2>

            <div class="form-group">
                <label><strong>Theme</strong></label>
                <div class="radio-group">
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <label class="radio-item">
                            <input type="radio" name="theme" value="@theme" checked="@(_theme == theme)" @onchange="() => _theme = theme" />
                            <span>@theme</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label><strong>Font Size</strong></label>
                <div class="radio-group">
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <label class="radio-item">
                            <input type="radio" name="fontSize" value="@size" checked="@(_fontSize == size)" @onchange="() => _fontSize = size" />
                            <span>@size</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label><strong>Language</strong></label>
                <select @bind="_language">
                    <option value="English">English</option>
                    <option value="Spanish">Spanish</option>
                    <option value="French">French</option>
                    <option value="German">German</option>
                    <option value="Japanese">Japanese</option>
                </select>
            </div>

            <label class="toggle-row">
                <span><strong>Compact Mode</strong></span>
                <input type="checkbox" @bind="_compactMode" class="toggle-switch" />
            </label>

            <h3>Preview</h3>
            <div class="appearance-preview @_theme.ToLowerInvariant() @_fontSize.ToLowerInvariant() @(_compactMode ? "compact" : "")">
                <div class="preview-header">Sample Header</div>
                <p class="preview-text">This is how your content will look with the selected settings.</p>
                <button class="preview-button">Sample Button</button>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
            </div>
        </section>
    };

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }
}

.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

/* Sidebar */
.settings-sidebar {
    width: 240px;
    background: #f8f9fa;
    border-right: 1px solid #e0e0e0;
    padding: 1.5rem 0;
    flex-shrink: 0;
}

.settings-sidebar h2 {
    padding: 0 1.5rem;
    margin: 0 0 1rem;
    font-size: 1.25rem;
    color: #333;
}

.settings-sidebar ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-sidebar li {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.5rem;
    cursor: pointer;
    color: #555;
    transition: all 0.15s ease;
    border-left: 3px solid transparent;
}

.settings-sidebar li:hover {
    background: #e9ecef;
    color: #333;
}

.settings-sidebar li.active {
    background: #e7f1ff;
    color: #0d6efd;
    border-left-color: #0d6efd;
    font-weight: 600;
}

.nav-icon {
    font-size: 1.1rem;
}

/* Main content */
.settings-content {
    flex: 1;
    padding: 2rem 3rem;
    max-width: 800px;
    position: relative;
}

.settings-section h2 {
    margin: 0 0 1.5rem;
    font-size: 1.5rem;
    color: #222;
}

.settings-section h3 {
    margin: 1.5rem 0 0.75rem;
    font-size: 1.1rem;
    color: #444;
}

/* Form elements */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-size: 0.9rem;
    color: #555;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
    width: 100%;
    padding: 0.6rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 6px;
    font-size: 0.95rem;
    transition: border-color 0.15s;
}

.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
    outline: none;
    border-color: #0d6efd;
    box-shadow: 0 0 0 3px rgba(13, 110, 253, 0.1);
}

.form-actions {
    margin-top: 1.5rem;
    display: flex;
    gap: 0.75rem;
}

/* Buttons */
.btn {
    padding: 0.6rem 1.25rem;
    border: none;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.15s;
}

.btn-primary {
    background: #0d6efd;
    color: white;
}

.btn-primary:hover {
    background: #0b5ed7;
}

.btn-secondary {
    background: #6c757d;
    color: white;
}

.btn-secondary:hover {
    background: #5c636a;
}

